// A tiling desktop of 2026 around the scene it wraps, after Omarchy 4 ("Quattro"):
// one thin bar along the top and the scene in a tile with gaps and a colored
// border, no title bar. The bar's left has the menu, the workspaces, the
// workspace's layout and the window with the focus; its middle the day and the
// time; its right the signal and the battery, which open the frame's Setup. A
// double click on its empty stretch makes it transparent. Built-in scenes are
// drawn in the tile too.
//
// On a frame that runs its scenes side by side (app.frame.scenes is there), it is
// a desktop: every scene opened is a tile on the workspace showing, and they all
// run at once (on an ESP32 as many as app.frame.windows says, and one more opened
// closes the one that had the focus longest ago), and chosen in another desktop's
// place (the frame page's Layout), it opens what that one had open, left to right.
// A workspace is tiled in one of three layouts, and Super+L (or the layout's mark
// in the bar) goes through them: dwindle (each new tile takes half of the last
// one's room, side by side where it is wide, Super+J turns that around),
// scrolling (columns half the desktop wide in a strip that scrolls to the one
// with the focus) and floating (windows with a title bar, opened at their scene's
// own size where there is room, moved and sized with the mouse, and a dock along
// the bottom with the frame's own apps and the windows open). A press in a tile
// gives it the focus. Super+Space opens the menu: the frame's own apps and scenes
// by category, and Setup, the theme, the layout, the window's own commands and the
// key bindings, with a field that filters all of it. The keys are Omarchy's,
// Super being the key the field `superKey` says (Super, Ctrl, Alt, or Super or
// Ctrl, the default: a browser keeps Cmd+W and Cmd+Space, and no Mac binds
// Ctrl): Super+1 to 9 a workspace (with Shift, the window goes there), Super+Tab the next
// one, Super+W or Q closes, Super+F full screen, Super+M puts a floating window in
// the dock, Super+arrows move the focus (with Shift, the tiles swap), Super+Return
// the terminal, Super+Shift+F Files, Super+K the bindings, Super+Ctrl+W (N, P, A,
// B) Setup, Super+Shift+Ctrl+Space the next theme, Alt+Tab the next window. The
// frame's own scenes are tiles too ("Clock settings", "Setup", "Scenes"), stay
// open while another has the focus, and close when they go back by themselves.
const pad = (n) => String(n).padStart(2, '0')
const on = (value) => value === true || value === 'true'

// The frame's own scenes (the contract's `scenes.settings` and `scenes.switcher`),
// and the command that opens each, which also sends it back.
const SETTINGS = 'system/sceneSettings'
// On a desktop every scene's settings are a scene of their own, this and the
// scene's id (the contract's `scenes.settingsWindow`); the plain id is the frame's
// page, Setup.
const SETTINGS_OF = 'system/sceneSettings#'
const settingsOf = (id) => SETTINGS_OF + id
const settingsFor = (id) => (typeof id === 'string' && id.startsWith(SETTINGS_OF) ? id.slice(SETTINGS_OF.length) : null)
const SWITCHER = 'system/sceneSwitcher'
const commandOf = (id) => (id === SWITCHER ? 'sceneSwitcher' : 'sceneSettings')
const isSystem = (id) => typeof id === 'string' && id.startsWith('system/')
// The frame's own apps that are scenes like any other, which the frame may have
// (docs/scene-store.md, docs/terminal.md): the scene store, Files and the
// terminal, by their sample's id, or by their name where a control plane gave
// them another id (Files by its old name too, "Asset browser"). A desktop has
// entries of its own for them, and leaves them out of its scene lists.
const appIs = (id, ...names) => (scene) =>
  !!scene && (scene.id === id || names.includes(String(scene.name || '').trim().toLowerCase()))
const isStore = appIs('scene-store', 'scene store')
const isFiles = appIs('asset-browser', 'files', 'asset browser')
const isTerminal = appIs('terminal-app', 'terminal')
const isFrameApp = (scene) => isStore(scene) || isFiles(scene) || isTerminal(scene)
// A list of scenes in groups by their category (`category` on each entry of
// app.frame.scenes: the scene's settings.category, its name, "Photos"): one
// group under each name, the groups by name whatever the case, and the scenes
// with none (or "Other") last, as Other. Where no scene has one, one group with
// no title: the list as it always was. Every desktop with a list of scenes has
// this same function.
function grouped(scenes) {
  const nameOf = (scene) => {
    const name = typeof scene.category === 'string' ? scene.category.trim() : ''
    return name.toLowerCase() === 'other' ? '' : name
  }
  const names = []
  for (const scene of scenes) {
    const name = nameOf(scene)
    if (name && !names.includes(name)) names.push(name)
  }
  if (!names.length) return [{ title: null, scenes }]
  names.sort((a, b) => {
    const x = a.toLowerCase()
    const y = b.toLowerCase()
    return x < y ? -1 : x > y ? 1 : a < b ? -1 : a > b ? 1 : 0
  })
  const groups = names.map((title) => ({ title, scenes: scenes.filter((scene) => nameOf(scene) === title) }))
  const rest = scenes.filter((scene) => !nameOf(scene))
  if (rest.length) groups.push({ title: 'Other', scenes: rest })
  return groups
}
// A scene's own icon (`icon` on its entry of app.frame.scenes, docs/scene-icons.md):
// one path in a 24 box, filled in the color of the text around it, `size` wide
// and high (a length); null where the scene has none, and the desktop draws its
// own. Every desktop that draws its scenes' icons has this same function.
function ownIcon(scene, size) {
  if (!scene || typeof scene.icon !== 'string' || !scene.icon) return null
  return (
    <svg viewBox="0 0 24 24" className={`shrink-0 w-[${size}] h-[${size}]`}>
      <path d={scene.icon} fill="currentColor" />
    </svg>
  )
}
const findScene = (app, test) => (Array.isArray(app.frame.scenes) ? app.frame.scenes.find(test) : undefined)
const storeOf = (app) => findScene(app, isStore)
const filesOf = (app) => findScene(app, isFiles)
const terminalOf = (app) => findScene(app, isTerminal)

// ---------------------------------------------------------------- the themes
//
// The desktop's colors, after Omarchy's themes: the page behind everything, the
// wallpaper's second color, the bar, the text, the quieter text and the borders
// of the tiles without the focus, and the accent (the tile with the focus, the
// workspace showing, what is picked). The field `scheme` picks one, and
// Super+Shift+Ctrl+Space goes to the next.
const SCHEMES = {
  'tokyo-night': { name: 'Tokyo Night', bg: '#1a1b26', wall: '#24283b', bar: '#16161e', fg: '#c0caf5', muted: '#565f89', accent: '#7aa2f7' },
  catppuccin: { name: 'Catppuccin', bg: '#1e1e2e', wall: '#313244', bar: '#181825', fg: '#cdd6f4', muted: '#6c7086', accent: '#89b4fa' },
  'catppuccin-latte': { name: 'Catppuccin Latte', bg: '#eff1f5', wall: '#dce0e8', bar: '#e6e9ef', fg: '#4c4f69', muted: '#9ca0b0', accent: '#1e66f5' },
  everforest: { name: 'Everforest', bg: '#2d353b', wall: '#3d484d', bar: '#272e33', fg: '#d3c6aa', muted: '#859289', accent: '#a7c080' },
  'flexoki-light': { name: 'Flexoki Light', bg: '#fffcf0', wall: '#e6e4d9', bar: '#f2f0e5', fg: '#100f0f', muted: '#878580', accent: '#205ea6' },
  gruvbox: { name: 'Gruvbox', bg: '#282828', wall: '#3c3836', bar: '#1d2021', fg: '#ebdbb2', muted: '#928374', accent: '#d79921' },
  kanagawa: { name: 'Kanagawa', bg: '#1f1f28', wall: '#2a2a37', bar: '#16161d', fg: '#dcd7ba', muted: '#727169', accent: '#7e9cd8' },
  'matte-black': { name: 'Matte Black', bg: '#121212', wall: '#1e1e1e', bar: '#0b0b0b', fg: '#bebebe', muted: '#595959', accent: '#e68e0d' },
  nord: { name: 'Nord', bg: '#2e3440', wall: '#3b4252', bar: '#242933', fg: '#d8dee9', muted: '#616e88', accent: '#88c0d0' },
  ristretto: { name: 'Ristretto', bg: '#2c2525', wall: '#403838', bar: '#211c1c', fg: '#e6d9db', muted: '#72696a', accent: '#f38d70' },
  'rose-pine': { name: 'Rose Pine', bg: '#faf4ed', wall: '#f2e9e1', bar: '#fffaf3', fg: '#575279', muted: '#9893a5', accent: '#d7827e' },
}
const SCHEME_IDS = Object.keys(SCHEMES)
const schemeOf = (app) => {
  const id = SCHEMES[String(app.state.scheme || '')] ? String(app.state.scheme) : 'tokyo-night'
  return { id, ...SCHEMES[id] }
}

// ------------------------------------------------------------ the frame's pages
//
// The frame's own pages (a scene's settings, the frame's, the scene list, the
// keyboard on the screen) in this layout's look: a theme is each
// kind of element's classes (docs/jsx-ui.md "Themes"), a string for one box or a
// list for boxes inside each other. The layout keeps it in its state as `theme`,
// where the frame reads it; not on e-paper but for high contrast. "Omarchy" is the
// desktop's own theme's colors.
const CONTRAST = {
  page: 'bg-black text-white',
  bar: 'border-b-2 border-white',
  button: 'font-bold bg-black text-white border-2 border-white active:bg-white active:text-black',
  primary: 'font-bold bg-white text-black border-2 border-white active:bg-black active:text-white',
  selected: 'bg-white text-black border-2 border-white',
  field: 'bg-black text-white border-2 border-white placeholder:text-white focus:border-[#ffff00]',
  option: 'active:bg-white active:text-black',
  picked: 'bg-white text-black',
  switch: 'rounded-full border-2 border-white',
  switchOn: 'rounded-full bg-white border-2 border-white',
  knob: 'rounded-full bg-white',
  knobOn: 'rounded-full bg-black',
  muted: 'text-white',
  card: 'border-2 border-white',
  tile: 'bg-black text-white border-2 border-white active:bg-white active:text-black',
  tileLit: 'bg-black text-white border-4 border-[#ffff00]',
  accent: 'bg-[#ffff00]',
  keyboard: 'bg-black text-white border-t-2 border-white',
  key: 'bg-black text-white border-2 border-white active:bg-white active:text-black',
  keyMod: 'bg-black text-[#ffff00] border-2 border-white active:bg-white active:text-black',
  keyLit: 'bg-white text-black border-2 border-white',
}

const rolesOf = (t) => ({
  page: `bg-[${t.bg}] text-[${t.fg}]`,
  bar: `border-b-1 border-[${t.muted}]`,
  button: `bg-[${t.bar}] text-[${t.fg}] border-1 border-[${t.muted}] active:bg-[${t.accent}] active:text-[${t.bg}]`,
  primary: `bg-[${t.accent}] text-[${t.bg}] border-1 border-[${t.accent}] active:bg-[${t.fg}]`,
  selected: `bg-[${t.bar}] text-[${t.accent}] border-2 border-[${t.accent}]`,
  field: `bg-[${t.bar}] text-[${t.fg}] border-1 border-[${t.muted}] placeholder:text-[${t.muted}] focus:border-[${t.accent}]`,
  option: `active:bg-[${t.accent}] active:text-[${t.bg}]`,
  picked: `bg-[${t.accent}] text-[${t.bg}]`,
  switch: `rounded-full bg-[${t.bar}] border-1 border-[${t.muted}]`,
  switchOn: `rounded-full bg-[${t.accent}] border-1 border-[${t.accent}]`,
  knob: `rounded-full bg-[${t.fg}]`,
  knobOn: `rounded-full bg-[${t.bg}]`,
  muted: `text-[${t.muted}]`,
  card: `bg-[${t.bar}] border-1 border-[${t.muted}]`,
  tile: `bg-[${t.bar}] text-[${t.fg}] border-1 border-[${t.muted}] active:border-[${t.accent}]`,
  tileLit: `bg-[${t.bar}] text-[${t.fg}] border-2 border-[${t.accent}]`,
  accent: `bg-[${t.accent}]`,
  keyboard: `bg-[${t.bar}] text-[${t.fg}] border-t-1 border-[${t.muted}]`,
  key: `bg-[${t.bg}] text-[${t.fg}] border-1 border-[${t.muted}] active:bg-[${t.accent}] active:text-[${t.bg}]`,
  keyMod: `bg-[${t.bg}] text-[${t.accent}] border-1 border-[${t.muted}] active:bg-[${t.accent}] active:text-[${t.bg}]`,
  keyLit: `bg-[${t.accent}] text-[${t.bg}] border-1 border-[${t.accent}]`,
})

function dress(app, t) {
  const name = String(app.state.look || 'omarchy')
  const theme = name === 'contrast' ? CONTRAST : app.frame.paper ? null : name === 'omarchy' ? rolesOf(t) : null
  const key = theme ? (name === 'omarchy' ? `omarchy:${t.id}` : name) : ''
  if ((app.state.themeOf || '') === key) return
  frameos.setState('theme', theme)
  frameos.setState('themeOf', key)
}

// Sizes are pixels of the desktop's own: twice that from a short side of 2160 (a 4K
// screen), or of 1000 on e-paper, whose pixels are small, and in proportion under
// 480, which has no room for them. The frame's render scale multiplies on top, which
// a size given as a share of the panel could not do.
let zoom = 1
const px = (n) => `${Math.round(n * zoom * 10) / 10}px`
const size = (n) => Math.round(n * zoom)
// The bar's height: the desktop starts under it. Hyprland's gaps (around the
// tiles and between them) and border.
const barH = () => size(26)
const gapOut = () => size(10)
const gapIn = () => size(10)
const border = () => Math.max(1, size(2))
const titleH = () => size(26)
// A floating workspace's dock, and the band along the bottom it takes from the
// windows that fill the desktop or half of it.
const dockH = () => size(54)
const dockSpace = () => dockH() + size(10)

const DAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday']

function clock(now, twentyFour) {
  const minutes = pad(now.getMinutes())
  if (twentyFour) return `${pad(now.getHours())}:${minutes}`
  return `${now.getHours() % 12 || 12}:${minutes} ${now.getHours() < 12 ? 'AM' : 'PM'}`
}

// Which key stands for Super (the field `superKey`): Super itself (Cmd on a
// Mac, the Windows key), Ctrl, Alt, or Super or Ctrl, the default. A key with
// it held is a binding; the modifiers that do not stand for Super are the
// binding's own (Super+Ctrl+W is Cmd+Ctrl+W where Ctrl is Super too).
const SUPER_KEYS = ['both', 'super', 'ctrl', 'alt']
const superMode = (app) => (SUPER_KEYS.includes(String(app.state.superKey)) ? String(app.state.superKey) : 'both')
function chordOf(app, p) {
  const mode = superMode(app)
  const viaMeta = p.meta === true && (mode === 'super' || mode === 'both')
  const viaCtrl = !viaMeta && p.ctrl === true && (mode === 'ctrl' || mode === 'both')
  const viaAlt = p.alt === true && mode === 'alt'
  return {
    sup: viaMeta || viaCtrl || viaAlt,
    ctrl: p.ctrl === true && !viaCtrl,
    alt: p.alt === true && !viaAlt,
    shift: p.shift === true,
  }
}
// The name a binding is shown with, and whether one that also needs Ctrl can
// be pressed at all (not where Ctrl is the only Super).
const superName = (app) => ({ ctrl: 'Ctrl', alt: 'Alt' }[superMode(app)] || 'Super')
const withCtrl = (app) => superMode(app) !== 'ctrl'

// The ISO week, which a click on the clock adds.
function isoWeek(now) {
  const d = new Date(Date.UTC(now.getFullYear(), now.getMonth(), now.getDate()))
  d.setUTCDate(d.getUTCDate() + 4 - (d.getUTCDay() || 7))
  return Math.ceil(((d - Date.UTC(d.getUTCFullYear(), 0, 1)) / 86400000 + 1) / 7)
}

// ---------------------------------------------------------------- the pieces

const Glyph = ({ s = 16, w, vb = '0 0 16 16', children }) => (
  <svg viewBox={vb} className={`shrink-0 w-[${px(w || s)}] h-[${px(s)}]`}>
    {children}
  </svg>
)

// The menu's mark: a ring.
const MenuGlyph = ({ c }) => (
  <Glyph>
    <circle cx="8" cy="8" r="5" fill="none" stroke={c} strokeWidth="2.6" />
  </Glyph>
)

// A workspace's layout: dwindle's halves, scrolling's columns, floating's windows.
const LayoutGlyph = ({ how, c }) => (
  <Glyph s={13}>
    {how === 'floating' ? (
      <g fill="none" stroke={c} strokeWidth="1.6">
        <rect x="1" y="1" width="9" height="8" />
        <rect x="6" y="6" width="9" height="9" />
      </g>
    ) : how === 'scrolling' ? (
      <g fill={c}>
        <rect x="0" y="2" width="2" height="12" />
        <rect x="4" y="2" width="8" height="12" />
        <rect x="14" y="2" width="2" height="12" />
      </g>
    ) : (
      <g fill={c}>
        <rect x="1" y="1" width="6" height="14" />
        <rect x="9" y="1" width="6" height="6" />
        <rect x="9" y="9" width="6" height="6" />
      </g>
    )}
  </Glyph>
)

// The Wi-Fi's arcs, lit as far as the signal reaches; nothing on a frame that
// cannot tell.
function WifiGlyph({ rssi, c, dim }) {
  if (typeof rssi !== 'number') return null
  const level = rssi >= -55 ? 4 : rssi >= -65 ? 3 : rssi >= -75 ? 2 : 1
  const at = (n) => (level >= n ? c : dim)
  return (
    <Glyph s={13} w={17} vb="0 0 16 12">
      <path d="M1 4.6a10 10 0 0 1 14 0" fill="none" stroke={at(4)} strokeWidth="1.7" />
      <path d="M3.4 7.1a6.6 6.6 0 0 1 9.2 0" fill="none" stroke={at(3)} strokeWidth="1.7" />
      <path d="M5.8 9.5a3.2 3.2 0 0 1 4.4 0" fill="none" stroke={at(2)} strokeWidth="1.7" />
      <circle cx="8" cy="11.2" r="0.9" fill={c} />
    </Glyph>
  )
}

function BatteryGlyph({ percent, c, low }) {
  if (typeof percent !== 'number') return null
  return (
    <Glyph s={11} w={21} vb="0 0 21 11">
      <rect x="0.7" y="0.7" width="17" height="9.6" rx="2" fill="none" stroke={c} strokeWidth="1.4" />
      <rect x="18.6" y="3.5" width="2" height="4" rx="0.8" fill={c} />
      <rect x="2.4" y="2.4" width={Math.max(0.5, (13.6 * percent) / 100)} height="6.2" rx="1" fill={percent > 15 ? c : low} />
    </Glyph>
  )
}

// A floating window's buttons.
const CloseGlyph = ({ c }) => (
  <Glyph s={10} vb="0 0 10 10">
    <path d="M1.5 1.5L8.5 8.5M8.5 1.5L1.5 8.5" fill="none" stroke={c} strokeWidth="1.6" />
  </Glyph>
)
const MaxGlyph = ({ c }) => (
  <Glyph s={10} vb="0 0 10 10">
    <rect x="1.5" y="1.5" width="7" height="7" fill="none" stroke={c} strokeWidth="1.4" />
  </Glyph>
)
const MinGlyph = ({ c }) => (
  <Glyph s={10} vb="0 0 10 10">
    <path d="M1.5 8H8.5" fill="none" stroke={c} strokeWidth="1.6" />
  </Glyph>
)

// The dock's button for the whole menu: a grid of nine.
const GridGlyph = ({ c }) => (
  <Glyph s={18}>
    <g fill={c}>
      {[1, 6.5, 12].flatMap((y) => [1, 6.5, 12].map((x) => <rect x={x} y={y} width="3.5" height="3.5" />))}
    </g>
  </Glyph>
)

const SearchGlyph = ({ c }) => (
  <Glyph s={15}>
    <circle cx="6.5" cy="6.5" r="4.6" fill="none" stroke={c} strokeWidth="1.8" />
    <path d="M10 10L14.5 14.5" fill="none" stroke={c} strokeWidth="1.8" />
  </Glyph>
)

// The frame's own apps and a scene with no icon of its own: its first letter in a
// square, the frame's own apps in the accent.
const Letter = ({ text, t, s = 16, lit = false }) => (
  <div
    className={`flex items-center justify-center shrink-0 w-[${px(s)}] h-[${px(s)}] text-[${px(Math.round(s * 0.62))}] font-bold ${
      lit ? `bg-[${t.accent}] text-[${t.bg}]` : `bg-[${t.muted}] text-[${t.bg}]`
    }`}
  >
    {String(text || '?').trim().charAt(0).toUpperCase() || '?'}
  </div>
)

// The bar: its three parts, the left and the right taking what the middle leaves.
const Bar = ({ t, clear, className = '', left, middle, right, ...handlers }) => (
  <div
    className={`flex items-center h-[${barH()}px] px-[${px(6)}] gap-[${px(8)}] text-[${t.fg}] text-[${px(13)}] ${clear ? '' : `bg-[${t.bar}]`} ${className}`}
    onPointerDown={() => {}}
    {...handlers}
  >
    <div className={`flex flex-1 basis-0 min-w-0 items-center gap-[${px(6)}] self-stretch`}>{left}</div>
    <div className="flex shrink-0 items-center">{middle}</div>
    <div className={`flex flex-1 basis-0 min-w-0 items-center justify-end gap-[${px(8)}] self-stretch`}>{right}</div>
  </div>
)

// What the frame knows of itself, at the bar's right: it opens Setup.
const Tray = ({ app, t, onClick }) => (
  <div className={`flex items-center shrink-0 gap-[${px(8)}] px-[${px(4)}] self-stretch active:bg-[${t.muted}]`} onClick={onClick}>
    <WifiGlyph rssi={app.frame.wifiRssi} c={t.fg} dim={t.muted} />
    <BatteryGlyph percent={app.frame.batteryPercent} c={t.fg} low="#f7768e" />
    {on(app.state.percent) && typeof app.frame.batteryPercent === 'number' ? (
      <span className="whitespace-nowrap">{`${Math.round(app.frame.batteryPercent)}%`}</span>
    ) : null}
  </div>
)

// ---------------------------------------------------------------- the desktop
//
// What it keeps, in the layout's state (it goes along from scene to scene, and
// is gone at a restart): `wins`, the windows open in the order they were opened
// (dwindle and scrolling tile them in that order), each {id, ws, x, y, w, h, z,
// max, min, snap}: its workspace, and its own box on a floating workspace, in the
// desktop's pixels (`max` filling the desktop, `snap` a half, `min` in the dock;
// a built-in scene's also its `title`); `ws`, the workspace showing; `layouts`,
// each workspace's layout by number ('dwindle' when it says none); `flip`, the
// workspaces whose dwindle splits are turned around; `scroll`, how far each
// scrolling strip is scrolled; `boxes`, where each scene's floating window was
// when it closed; `last`, the scene that had the focus at the last render;
// `asked`, the scene this layout last brought forward itself; `gone`, the scene
// whose window was just closed; `menu` ('palette'), with its `page`, `query` and
// `pick`; `clear`, the bar transparent; `week`, the clock with the week;
// `percent`, the battery's percentage; `full`, `peek` and `drag`.

const winsOf = (app) => (Array.isArray(app.state.wins) ? app.state.wins : [])
const topZ = (wins) => wins.reduce((z, w) => Math.max(z, w.z || 0), 0)
const wsOf = (app) => Math.max(1, Math.round(Number(app.state.ws) || 1))
const layoutOf = (app, ws) => {
  const how = app.state.layouts && app.state.layouts[ws]
  return how === 'scrolling' || how === 'floating' ? how : 'dwindle'
}
const LAYOUTS = ['dwindle', 'scrolling', 'floating']
const LAYOUT_NAMES = { dwindle: 'Dwindle', scrolling: 'Scrolling', floating: 'Floating' }

function clamp(win, deskW, deskH) {
  const minW = Math.min(deskW, size(160))
  const minH = Math.min(deskH, size(100))
  win.w = Math.round(Math.max(minW, Math.min(win.w, deskW)))
  win.h = Math.round(Math.max(minH, Math.min(win.h, deskH)))
  // A title bar stays where the pointer can get at it.
  const grip = size(48)
  win.x = Math.round(Math.max(grip - win.w, Math.min(win.x, deskW - grip)))
  win.y = Math.round(Math.max(0, Math.min(win.y, deskH - size(26))))
  return win
}

// The windows' boxes are in the desktop's pixels, and the desktop is the
// panel over the render scale: a new scale, a turn or a resized browser window
// gives it another size, and boxes made for the old one sat small in a corner
// or off the glass (2026-11-16). `room` is the desktop they were made for; on
// another, each window, and each closed one's box, keeps its place and size as
// a share of the desktop.
function refit(app, wins, fresh, deskW, deskH) {
  const room = app.state.room
  if (room && room.w === deskW && room.h === deskH) return wins
  frameos.setState('room', { w: deskW, h: deskH })
  if (fresh || !room || !(room.w > 0 && room.h > 0)) return wins
  const fit = (b) =>
    clamp({ ...b, x: (b.x * deskW) / room.w, y: (b.y * deskH) / room.h, w: (b.w * deskW) / room.w, h: (b.h * deskH) / room.h }, deskW, deskH)
  const boxes = {}
  for (const [id, box] of Object.entries(boxesOf(app))) if (box) boxes[id] = fit(box)
  frameos.setState('boxes', boxes)
  const fitted = wins.map((w) => (w ? fit(w) : w))
  frameos.setState('wins', fitted)
  return fitted
}

const boxesOf = (app) => (app.state.boxes && typeof app.state.boxes === 'object' ? app.state.boxes : {})

// A closed window's box, for when its scene opens again.
function keep(app, win) {
  const { x, y, w, h, max, snap } = win
  frameos.setState('boxes', { ...boxesOf(app), [win.id]: { x, y, w, h, max, snap } })
}

// The scene's own area in a new window, in a desktop's pixels like every size
// here: its own size where it says one (`windowSize` in app.frame.scenes, its
// settings.windowSize, `WxH`), with `own` set, else 800 x 480, a 7.5-inch
// frame's. Every desktop of windows has this same function.
function ownSize(app, id) {
  const scene = Array.isArray(app.frame.scenes) ? app.frame.scenes.find((s) => s.id === id) : null
  const mine = scene ? /^(\d+)x(\d+)$/.exec(String(scene.windowSize || '')) : null
  const w = mine ? Number(mine[1]) : 800
  const h = mine ? Number(mine[2]) : 480
  return { w: Math.round(w * zoom), h: Math.round(h * zoom), own: !!mine }
}

// Where a new window w by h goes in `area` ({x, y, w, h}): all of it on bare
// desktop where it fits, clear of the windows shown (`shown`, their boxes) and of
// what the desktop keeps clear (`clear`: its icons). Where nothing is free, off
// the icons if it can be, then where it covers the least of the windows, a title
// bar (`bar` high) counting five times over, so no window opens right over
// another's title bar. The spots tried are the area's corners and thirds, `gap`
// beside each box and a title bar down from each window, each a sum over the
// boxes: a few hundred with a few windows open, and only when one opens, cheap
// enough for an ESP32. The highest free spot wins, then the leftmost. Every
// desktop of windows has this same function (docs/scene-layouts.md "Windows").
function freeSpot(w, h, area, shown, clear, bar, gap) {
  // `gap` from the area's edges too, where the window leaves room for it.
  const roomX = Math.max(0, area.w - w)
  const roomY = Math.max(0, area.h - h)
  const left = area.x + Math.min(gap, roomX / 2)
  const top = area.y + Math.min(gap, roomY / 2)
  const right = area.x + roomX - Math.min(gap, roomX / 2)
  const bottom = area.y + roomY - Math.min(gap, roomY / 2)
  const xs = []
  const ys = []
  const put = (list, v, lo, hi) => {
    const at = Math.round(Math.max(lo, Math.min(v, hi)))
    if (list.indexOf(at) < 0) list.push(at)
  }
  for (let i = 0; i <= 3; i++) {
    put(xs, left + ((right - left) * i) / 3, left, right)
    put(ys, top + ((bottom - top) * i) / 3, top, bottom)
  }
  for (const b of shown.concat(clear)) {
    put(xs, b.x + b.w + gap, left, right)
    put(xs, b.x - w - gap, left, right)
    put(ys, b.y + b.h + gap, top, bottom)
    put(ys, b.y - h - gap, top, bottom)
  }
  for (const b of shown) {
    put(xs, b.x + bar, left, right)
    put(ys, b.y + bar, top, bottom)
  }
  xs.sort((a, b) => a - b)
  ys.sort((a, b) => a - b)
  // How much of a box's top `down` pixels a window at x, y covers.
  const covered = (x, y, b, down) => {
    const across = Math.min(x + w, b.x + b.w) - Math.max(x, b.x)
    const deep = Math.min(y + h, b.y + down) - Math.max(y, b.y)
    return across > 0 && deep > 0 ? across * deep : 0
  }
  let best = null
  for (const y of ys)
    for (const x of xs) {
      let icons = 0
      for (const b of clear) icons += covered(x, y, b, b.h)
      let cost = 0
      for (const b of shown) cost += covered(x, y, b, b.h) + 4 * covered(x, y, b, Math.min(bar, b.h))
      if (icons === 0 && cost === 0) return { x, y }
      if (!best || icons < best.icons || (icons === best.icons && cost < best.cost)) best = { x, y, icons, cost }
    }
  return { x: best.x, y: best.y }
}

// What a floating window's frame takes around its scene: the border and the
// title bar.
const chromeW = () => 2 * border()
const chromeH = () => 2 * border() + titleH()

// A window's own box, for when its workspace floats: where it was when it
// closed, else its scene's own size where there is room on that workspace
// (freeSpot), and the desktop's most where it does not fit.
function placed(app, id, ws, wins, deskW, deskH, clear) {
  const win = { id, ws, z: topZ(wins) + 1 }
  const kept = boxesOf(app)[id]
  if (kept) return clamp({ ...kept, ...win }, deskW, deskH)
  const own = ownSize(app, id)
  const shown = wins.filter((other) => other.ws === ws && !other.min)
  const room = own.own ? Math.min((deskW - chromeW()) / own.w, (deskH - chromeH()) / own.h) : 1
  const shrink = room >= 1 || !shown.length ? 1 : 0.85 * room
  const w = Math.round(own.w * shrink) + chromeW()
  const h = Math.round(own.h * shrink) + chromeH()
  const fits = w <= deskW && h <= deskH
  const box = fits ? { w, h } : { w: Math.round(deskW * 0.62), h: Math.round(deskH * 0.62) }
  const boxes = shown.map((other) => boxOf(other, deskW, deskH))
  const at = freeSpot(box.w, box.h, { x: 0, y: 0, w: deskW, h: deskH }, boxes, clear, titleH(), gapOut())
  return clamp({ ...win, ...at, ...box, max: !fits && !shown.length }, deskW, deskH)
}

// Where each window is, for a desktop chosen in this one's place (`openPlaces`,
// handed over with `openScenes`): by scene id, its box as a share of the whole
// picture, so a desktop whose bars are elsewhere puts it where it was on the glass.
const share = (v) => Math.round(v * 10000) / 10000
function keepPlaces(app, drawn, width, height) {
  const places = {}
  for (const [id, b] of Object.entries(drawn))
    places[id] = {
      x: share(b.x / width), y: share(b.y / height), w: share(b.w / width), h: share(b.h / height),
      max: false, snap: null, min: !!b.min,
    }
  if (JSON.stringify(places) !== JSON.stringify(app.state.openPlaces || {})) frameos.setState('openPlaces', places)
}

// What another desktop had open when this layout was chosen in its place (its
// `openScenes`, handed over by the runtime: docs/scene-layouts.md "Windows"): a
// tile each on the first workspace, left to right as they were there
// (`openPlaces`), the one that had the focus brought forward last.
function opened(app, names, titleOf, deskW, deskH, clear) {
  const ids = []
  for (const id of Array.isArray(app.state.openScenes) ? app.state.openScenes : []) {
    if (typeof id === 'string' && !ids.includes(id) && (names[id] || isSystem(id))) ids.push(id)
  }
  const places = app.state.openPlaces && typeof app.state.openPlaces === 'object' ? app.state.openPlaces : {}
  const at = (id) => (places[id] && typeof places[id].x === 'number' ? places[id].x + places[id].y / 100 : 9)
  const order = ids.slice().sort((a, b) => at(a) - at(b))
  const wins = []
  for (const id of order) {
    const win = placed(app, id, 1, wins, deskW, deskH, clear)
    win.z = ids.indexOf(id) + 1
    if (isSystem(id)) win.title = titleOf(id, names)
    wins.push(win)
  }
  return wins
}

// What is open, the one with the focus last: what a layout chosen in this one's
// place opens (`openScenes`).
function keepOpen(app, wins, current) {
  const order = wins
    .filter((w) => w.id !== current)
    .sort((a, b) => (a.z || 0) - (b.z || 0))
    .map((w) => w.id)
  if (wins.some((w) => w.id === current)) order.push(current)
  if (JSON.stringify(order) !== JSON.stringify(app.state.openScenes || [])) frameos.setState('openScenes', order)
}

// A floating window's box: its own, the whole desktop, or a half of it.
function boxOf(win, deskW, deskH) {
  const half = Math.round(deskW / 2)
  if (win.max) return { x: 0, y: 0, w: deskW, h: deskH }
  if (win.snap === 'l') return { x: 0, y: 0, w: half, h: deskH }
  if (win.snap === 'r') return { x: half, y: 0, w: deskW - half, h: deskH }
  return { x: win.x, y: win.y, w: win.w, h: win.h }
}

// The tiles of a workspace, by window id, in the desktop's pixels: dwindle halves
// the room left for each next tile, across where it is wider than tall (the other
// way round where `flip`); scrolling puts each in a column half the desktop wide,
// in a strip `offset` scrolled; floating keeps each window's own box.
function tilesOf(list, how, deskW, deskH, flip, offset) {
  const out = gapOut()
  const inner = gapIn()
  const tiles = {}
  if (how === 'floating') {
    for (const w of list) tiles[w.id] = boxOf(w, deskW, Math.max(1, deskH - dockSpace()))
    return tiles
  }
  let room = { x: out, y: out, w: Math.max(1, deskW - 2 * out), h: Math.max(1, deskH - 2 * out) }
  if (how === 'scrolling') {
    const colW = list.length > 1 ? Math.round((room.w - inner) / 2) : room.w
    list.forEach((w, i) => {
      tiles[w.id] = { x: room.x + i * (colW + inner) - offset, y: room.y, w: colW, h: room.h }
    })
    return tiles
  }
  list.forEach((w, i) => {
    if (i === list.length - 1) {
      tiles[w.id] = room
      return
    }
    const across = flip ? room.w < room.h : room.w >= room.h
    if (across) {
      const first = Math.round((room.w - inner) / 2)
      tiles[w.id] = { x: room.x, y: room.y, w: first, h: room.h }
      room = { x: room.x + first + inner, y: room.y, w: room.w - first - inner, h: room.h }
    } else {
      const first = Math.round((room.h - inner) / 2)
      tiles[w.id] = { x: room.x, y: room.y, w: room.w, h: first }
      room = { x: room.x, y: room.y + first + inner, w: room.w, h: room.h - first - inner }
    }
  })
  return tiles
}

// Where the tiles of the workspace showing are, for the keys that move the focus
// between them: kept by the last render.
let drawnTiles = {}

// What a press, a key or the menu does to the windows. Each one reads the state
// afresh: a drag's moves come faster than renders.
function actions(app) {
  const current = app.frame.sceneId
  const update = (id, change) => {
    const next = winsOf(app).map((w) => (w.id === id ? { ...w, ...change(w) } : w))
    frameos.setState('wins', next)
  }
  const shut = () => frameos.setState('menu', null)
  // Every window this layout brings forward goes through here, so a built-in
  // scene that loses the focus some other way is known to have gone back.
  const go = (id) => {
    frameos.setState('asked', id)
    frameos.dispatch('setCurrentScene', { sceneId: id })
  }
  const windowOf = (id) => winsOf(app).find((w) => w.id === id)
  // A window given the focus: out of the dock, its workspace showing.
  const focus = (id) => {
    shut()
    const win = windowOf(id)
    update(id, () => ({ min: false }))
    if (win && win.ws) frameos.setState('ws', win.ws)
    if (id !== current) go(id)
  }
  const open = (id) => {
    shut()
    if (windowOf(id)) return focus(id)
    if (id !== current) go(id)
    else if (app.state.gone === id) frameos.setState('gone', null)
  }
  // Read when a handler runs, not when it was drawn: a press before it may have
  // brought another window forward.
  const showing = () => app.frame.sceneId
  // A built-in scene opens over a scene. Over another built-in one, that one stays
  // open in its tile, and the scene with the focus before comes forward to open it
  // over; with none, the built-in one goes back where it came from. Either way the
  // focus is this layout's doing (`asked`): the one left open keeps its tile.
  const overAScene = () => {
    const now = showing()
    if (!isSystem(now)) return
    // On the workspace showing: one on another would take the view there.
    const top = winsOf(app)
      .filter((w) => !isSystem(w.id) && !w.min && (w.ws || 1) === wsOf(app))
      .sort((a, b) => (b.z || 0) - (a.z || 0))[0]
    if (top) return go(top.id)
    // None: it goes back, done, and its window with it.
    frameos.setState('wins', winsOf(app).filter((w) => w.id !== now))
    frameos.dispatch(commandOf(now))
  }
  // A scene's settings: a tile of their own, opened over the scene brought forward
  // first; open already, that tile comes forward as it was left.
  const sceneSettings = (id) => {
    shut()
    if (windowOf(settingsOf(id))) return focus(settingsOf(id))
    if (id !== showing()) go(id)
    frameos.dispatch('sceneSettings', {})
    frameos.setState('asked', settingsOf(id))
  }
  // A built-in scene of the frame's, one tile each: Setup (the frame's page) and
  // the scene list. Open already, it comes forward as it was left.
  const builtIn = (id, command, payload) => () => {
    shut()
    if (windowOf(id)) return focus(id)
    overAScene()
    frameos.dispatch(command, payload)
    frameos.setState('asked', id)
  }
  const controlPanel = builtIn(SETTINGS, 'sceneSettings', { page: 'frame' })
  const sceneList = builtIn(SWITCHER, 'sceneSwitcher', {})
  // The window in front went away: the one before it on its workspace takes the
  // focus.
  const nextAfter = (id, skip = [id]) => {
    const win = windowOf(id)
    return winsOf(app)
      .filter((w) => !skip.includes(w.id) && !w.min && (!win || w.ws === win.ws))
      .sort((a, b) => (b.z || 0) - (a.z || 0))[0]
  }
  // In the dock (a floating workspace's).
  const minimize = (id) => {
    shut()
    update(id, () => ({ min: true }))
    const next = id === current ? nextAfter(id) : null
    if (next) go(next.id)
  }
  // A window closed, a scene's settings with it. The one in front: the next one
  // down takes the focus, as when it is put away, whatever scene it was opened
  // from. With none left the desktop is bare: a scene stays the frame's with no
  // window, and a built-in one goes back as its own Cancel does, the scene it
  // lands on opening no window either (app.frame.wentBack).
  const close = (id) => {
    shut()
    const ids = isSystem(id) ? [id] : [id, settingsOf(id)]
    const front = ids.includes(current)
    const next = front ? nextAfter(current, ids) : null
    const win = winsOf(app).find((w) => w.id === id)
    if (win) keep(app, win)
    frameos.setState('wins', winsOf(app).filter((w) => !ids.includes(w.id)))
    if (!front) return
    frameos.setState('full', false)
    if (next) return go(next.id)
    frameos.setState('gone', current)
    if (isSystem(current)) frameos.dispatch(commandOf(current))
  }
  const toggleMax = (id) => {
    shut()
    update(id, (w) => ({ max: !w.max, snap: null }))
  }
  const toggleFull = () => {
    shut()
    frameos.setState('peek', false)
    frameos.setState('full', !on(app.state.full))
  }
  // A workspace: its window that had the focus last comes forward; an empty one
  // shows the wallpaper.
  const toWorkspace = (n) => {
    shut()
    frameos.setState('ws', n)
    const top = winsOf(app)
      .filter((w) => w.ws === n && !w.min)
      .sort((a, b) => (b.z || 0) - (a.z || 0))[0]
    if (top && top.id !== showing()) go(top.id)
  }
  // The window with the focus to another workspace, and the focus with it.
  const moveTo = (id, n) => {
    shut()
    if (!windowOf(id)) return
    update(id, (w) => ({ ws: n, z: topZ(winsOf(app)) + 1, min: false }))
    frameos.setState('ws', n)
  }
  // The workspaces in the bar: one to five, and any further one in use.
  const lastWs = () => Math.max(5, wsOf(app), ...winsOf(app).map((w) => w.ws || 1))
  const stepWs = (step) => {
    const n = lastWs()
    toWorkspace(((wsOf(app) - 1 + step + n) % n) + 1)
  }
  const setLayout = (how) => {
    shut()
    frameos.setState('layouts', { ...(app.state.layouts || {}), [wsOf(app)]: how })
  }
  const cycleLayout = (step) => {
    const at = LAYOUTS.indexOf(layoutOf(app, wsOf(app)))
    setLayout(LAYOUTS[(at + step + LAYOUTS.length) % LAYOUTS.length])
  }
  const toggleSplit = () => {
    shut()
    const ws = wsOf(app)
    frameos.setState('flip', { ...(app.state.flip || {}), [ws]: !(app.state.flip && app.state.flip[ws]) })
  }
  // The tile nearest the one with the focus in a direction, of those drawn: given
  // the focus, or with `swap` its place in the order taken.
  const toward = (dir, swap) => {
    const from = drawnTiles[showing()]
    if (!from) return false
    const cx = from.x + from.w / 2
    const cy = from.y + from.h / 2
    let best = null
    for (const [id, b] of Object.entries(drawnTiles)) {
      if (id === showing()) continue
      const dx = b.x + b.w / 2 - cx
      const dy = b.y + b.h / 2 - cy
      const ahead = dir === 'left' ? -dx : dir === 'right' ? dx : dir === 'up' ? -dy : dy
      const aside = dir === 'left' || dir === 'right' ? Math.abs(dy) : Math.abs(dx)
      if (ahead <= 0) continue
      const cost = ahead + 2 * aside
      if (!best || cost < best.cost) best = { id, cost }
    }
    if (!best) return false
    if (!swap) {
      focus(best.id)
      return true
    }
    const all = winsOf(app).slice()
    const a = all.findIndex((w) => w.id === showing())
    const b = all.findIndex((w) => w.id === best.id)
    if (a < 0 || b < 0) return false
    const box = (w) => ({ x: w.x, y: w.y, w: w.w, h: w.h, max: w.max, snap: w.snap })
    const wa = all[a]
    const wb = all[b]
    all[a] = { ...wb, ...box(wa) }
    all[b] = { ...wa, ...box(wb) }
    frameos.setState('wins', all)
    return true
  }
  // Alt+Tab: the window that had the focus before this one, so twice comes back;
  // with Shift, the one at the bottom, so every window comes round in turn.
  const cycle = (back) => {
    const others = winsOf(app)
      .filter((w) => w.id !== current)
      .sort((a, b) => (b.z || 0) - (a.z || 0))
    const next = back ? others[others.length - 1] : others[0]
    if (next) focus(next.id)
    return !!next
  }
  // The menu, on one of its pages, the filter empty.
  const palette = (page) => {
    frameos.setState('query', '')
    frameos.setState('pick', 0)
    frameos.setState('page', page || null)
    frameos.setState('menu', 'palette')
  }
  const setScheme = (id) => frameos.setState('scheme', id)
  const nextScheme = () => {
    const at = SCHEME_IDS.indexOf(schemeOf(app).id)
    setScheme(SCHEME_IDS[(at + 1) % SCHEME_IDS.length])
  }
  return {
    update, focus, open, sceneSettings, controlPanel, sceneList, minimize, close, toggleMax, toggleFull, toWorkspace,
    moveTo, stepWs, setLayout, cycleLayout, toggleSplit, toward, cycle, palette, setScheme, nextScheme, shut,
  }
}

// What a built-in scene's tile is called before it has shown its page here.
const titleOf = (id, names) => {
  const scene = settingsFor(id)
  if (scene) return `${names[scene] || scene} settings`
  return id === SWITCHER ? 'Scenes' : 'Setup'
}

// What a built-in scene's tile is called, by the page it shows.
function systemTitle(app, names) {
  const scene = settingsFor(app.frame.sceneId)
  if (scene) return `${names[scene] || app.state.openedOver || scene} settings`
  if (app.frame.sceneId === SWITCHER) return 'Scenes'
  const page = app.frame.sceneName
  if (page === 'Frame settings') return 'Setup'
  if (page === 'Layout settings') return 'Appearance'
  return app.state.openedOver ? `${app.state.openedOver} settings` : 'Settings'
}

// A filter's match: the words of the label start with it, or it is in it.
const matches = (label, query) => {
  const text = String(label).toLowerCase()
  if (text.includes(query)) return true
  const initials = text
    .split(/[^a-z0-9]+/)
    .filter(Boolean)
    .map((word) => word[0])
    .join('')
  return initials.startsWith(query)
}

// The menu's runnable rows as the last render drew them, for its keys.
let paletteRows = []

function desktop(app, now, width, height) {
  const t = schemeOf(app)
  const scale = app.frame.scale || 1
  const builtIn = app.frame.systemScene === true
  const current = app.frame.sceneId
  const names = {}
  for (const scene of app.frame.scenes) names[scene.id] = scene.name || scene.id
  if (!builtIn && current && !names[current]) names[current] = app.frame.sceneName || current
  const store = storeOf(app)
  const files = filesOf(app)
  const terminal = terminalOf(app)
  const frameApps = [store, files, terminal].filter(Boolean)
  const programs = app.frame.scenes.filter((scene) => !isFrameApp(scene))
  const sceneOf = (id) => app.frame.scenes.find((scene) => scene.id === id)
  const deskTop = barH()
  const deskW = width
  const deskH = Math.max(1, height - deskTop)
  let ws = wsOf(app)
  // A floating workspace's dock along the bottom: new windows keep clear of it,
  // and one filling the desktop or a half of it stops above it.
  const dockBox = (count) => {
    const w = size(12) + count * size(46)
    return { x: Math.round((deskW - w) / 2), y: deskH - dockH() - size(6), w, h: dockH() }
  }
  const usable = (n) => (layoutOf(app, n) === 'floating' ? Math.max(1, deskH - dockSpace()) : deskH)

  // Whatever brought a scene forward (a tile, the menu, the scene list, a button,
  // the API), its window is open, on the workspace showing if it is new, and its
  // workspace shows. A built-in scene's tile is named by what it shows while it
  // has the focus, and closes once it has gone back by itself: the focus left it
  // for a scene, and not because this layout moved it.
  // A layout just chosen in another desktop's place has no windows of its own yet:
  // it opens what that one had open.
  const fresh = !Array.isArray(app.state.wins)
  const saved = refit(app, fresh ? opened(app, names, titleOf, deskW, deskH, []) : winsOf(app), fresh, deskW, deskH)
  const wins = saved.filter((w) => w && (names[w.id] || isSystem(w.id))).map((w) => (w.ws ? w : { ...w, ws: 1 }))
  let changed = fresh ? wins.length > 0 : wins.length !== saved.length || saved.some((w) => w && !w.ws)
  if (current) {
    // The focus only came back here, from a built-in scene that went back by
    // itself (its Close, its Cancel, its timeout): a window closed stays closed
    // and one put away stays away. A scene chosen, from anywhere, opens, and so
    // does the first one a desktop just made shows.
    const quiet = !!app.state.last && app.state.last !== current && app.frame.wentBack === true
    let win = wins.find((w) => w.id === current)
    if (!win && app.state.gone !== current && !quiet) {
      const clear = layoutOf(app, ws) === 'floating' ? [dockBox(frameApps.length + 2)] : []
      win = placed(app, current, ws, wins, deskW, deskH, clear)
      wins.push(win)
      changed = true
    }
    if (win && builtIn && win.title !== systemTitle(app, names)) {
      win.title = systemTitle(app, names)
      changed = true
    }
    if (app.state.last !== current) {
      // Come back to quietly, a window on another workspace leaves the view here.
      if (win && !(quiet && (win.min || win.ws !== ws))) {
        win.min = false
        if (win.ws !== ws) {
          ws = win.ws
          frameos.setState('ws', ws)
        }
      }
      const before = wins.find((w) => w.id === app.state.last)
      if (before && isSystem(before.id) && !isSystem(current) && app.state.asked !== current) {
        keep(app, before)
        wins.splice(wins.indexOf(before), 1)
      } else if (before) before.z = topZ(wins) + 1
      if (win) win.z = topZ(wins) + 1
      if (quiet && !win) frameos.setState('gone', current)
      else if (app.state.gone && app.state.gone !== current) frameos.setState('gone', null)
      if (app.state.asked) frameos.setState('asked', null)
      frameos.setState('last', current)
      changed = true
      // Nothing of its own to show: the window on top takes the focus, as when
      // the one in front is closed.
      if (quiet && (!win || win.min || win.ws !== ws)) {
        const top = wins.filter((w) => !w.min && w.id !== current && w.ws === ws).sort((a, b) => (b.z || 0) - (a.z || 0))[0]
        if (top) {
          frameos.setState('asked', top.id)
          frameos.dispatch('setCurrentScene', { sceneId: top.id })
        }
      }
    }
  }
  // Where only so many scenes run at once (app.frame.windows, an ESP32's few),
  // one more closes the one that had the focus longest ago, its box kept.
  const most = app.frame.windows
  if (most > 0) {
    const others = wins.filter((w) => !isSystem(w.id) && w.id !== current).sort((a, b) => (a.z || 0) - (b.z || 0))
    const room = most - (current && !isSystem(current) && wins.some((w) => w.id === current) ? 1 : 0)
    const gone = others.slice(0, Math.max(0, others.length - room))
    if (gone.length) {
      const boxes = { ...boxesOf(app) }
      for (const win of gone) {
        const { x, y, w, h, max, snap } = win
        boxes[win.id] = { x, y, w, h, max, snap }
        wins.splice(wins.indexOf(win), 1)
      }
      frameos.setState('boxes', boxes)
      changed = true
    }
  }
  if (changed) frameos.setState('wins', wins)
  keepOpen(app, wins, current)
  for (const win of wins) if (isSystem(win.id)) names[win.id] = win.title || titleOf(win.id, names)

  // The tiles of every workspace, those of the one showing to draw. A scrolling
  // strip scrolls to the window with the focus.
  const how = layoutOf(app, ws)
  const flipOf = (n) => !!(app.state.flip && app.state.flip[n])
  const scrolls = app.state.scroll && typeof app.state.scroll === 'object' ? app.state.scroll : {}
  const listOf = (n) => wins.filter((w) => w.ws === n && !(layoutOf(app, n) === 'floating' && w.min))
  const strip = (n, list) => {
    let offset = Number(scrolls[n]) || 0
    const at = list.findIndex((w) => w.id === current)
    if (layoutOf(app, n) !== 'scrolling' || at < 0 || list.length < 2) return list.length < 2 ? 0 : offset
    const colW = Math.round((deskW - 2 * gapOut() - gapIn()) / 2)
    const left = gapOut() + at * (colW + gapIn())
    const furthest = (list.length - 2) * (colW + gapIn())
    if (left - offset < gapOut()) offset = left - gapOut()
    if (left + colW - offset > deskW - gapOut()) offset = left + colW - (deskW - gapOut())
    return Math.max(0, Math.min(offset, furthest))
  }
  const placesOf = {}
  for (const n of Array.from(new Set(wins.map((w) => w.ws)))) {
    const list = listOf(n)
    const offset = strip(n, list)
    if (n === ws && offset !== (Number(scrolls[n]) || 0)) frameos.setState('scroll', { ...scrolls, [n]: offset })
    const tiles = tilesOf(list, layoutOf(app, n), deskW, deskH, flipOf(n), offset)
    for (const [id, b] of Object.entries(tiles)) placesOf[id] = { ...b, y: b.y + deskTop }
    if (n === ws) drawnTiles = tiles
  }
  if (!wins.some((w) => w.ws === ws)) drawnTiles = {}
  keepPlaces(app, placesOf, width, height)

  const onWs = wins.filter((w) => w.ws === ws)
  const focused = onWs.find((w) => w.id === current && !w.min)
  const full = !!focused && on(app.state.full)
  const menu = app.state.menu || null
  const clearBar = on(app.state.clear)
  const isOpen = (id) => wins.some((w) => w.id === id)
  const a = actions(app)
  const { update, focus, open, sceneSettings, controlPanel, sceneList, minimize, close, toggleMax, toggleFull } = a

  // A floating window: a press on its title bar moves it, one on its border sizes
  // it from that edge; the moves that follow are captured by what was pressed. Let
  // go at the top of the desktop, a moved window fills it, at the left or right
  // edge it takes that half; dragged away again, it has its own size back.
  const startDrag = (drawn, mode) => (e) => {
    const win = winsOf(app).find((w) => w.id === drawn.id) || drawn
    const box = boxOf(win, deskW, usable(win.ws))
    const docked = !!(win.max || win.snap)
    if (docked && mode !== 'move') update(win.id, () => ({ ...box, snap: null }))
    frameos.setState('drag', {
      id: win.id,
      mode,
      x: e.x,
      y: e.y,
      from: box,
      own: { w: win.w, h: win.h },
      docked: docked && mode === 'move',
      at: null,
    })
    if (win.id !== current) focus(win.id)
  }
  const dragTo = (e) => {
    const drag = app.state.drag
    if (!drag || !e.buttons) return
    const dx = (e.x - drag.x) / scale
    const dy = (e.y - drag.y) / scale
    if (drag.mode === 'move') {
      const x = e.x / scale
      const y = e.y / scale - deskTop
      const at = y <= 2 ? 'max' : x <= 2 ? 'l' : x >= deskW - 3 ? 'r' : null
      if (drag.docked) {
        if (Math.abs(dx) + Math.abs(dy) < 8 * zoom) return
        const across = (drag.x / scale - drag.from.x) / drag.from.w
        const from = { x: drag.x / scale - across * drag.own.w, y: drag.from.y, w: drag.own.w, h: drag.own.h }
        frameos.setState('drag', { ...drag, at, docked: false, from })
        update(drag.id, () => ({ ...clamp({ ...from, x: from.x + dx, y: from.y + dy }, deskW, deskH), max: false, snap: null }))
        return
      }
      if (at !== drag.at) frameos.setState('drag', { ...drag, at })
    }
    const f = drag.from
    update(drag.id, () => {
      const box = { ...f }
      if (drag.mode === 'move') {
        box.x = f.x + dx
        box.y = f.y + dy
      } else {
        if (drag.mode.includes('l')) {
          box.x = Math.min(f.x + dx, f.x + f.w - 80 * zoom)
          box.w = f.w - (box.x - f.x)
        }
        if (drag.mode.includes('r')) box.w = f.w + dx
        if (drag.mode.includes('t')) {
          box.y = Math.max(0, Math.min(f.y + dy, f.y + f.h - 60 * zoom))
          box.h = f.h - (box.y - f.y)
        }
        if (drag.mode.includes('b')) box.h = f.h + dy
      }
      return clamp(box, deskW, deskH)
    })
  }
  const endDrag = () => {
    const drag = app.state.drag
    frameos.setState('drag', null)
    if (drag && drag.mode === 'move' && drag.at && !drag.docked) {
      update(drag.id, () => (drag.at === 'max' ? { max: true, snap: null } : { max: false, snap: drag.at }))
    }
  }
  const corner = 14 * zoom
  const edgeOf = (e) => {
    const x = e.localX < corner ? 'l' : e.localX > e.width - corner ? 'r' : ''
    const y = e.localY < corner ? 't' : e.localY > e.height - corner ? 'b' : ''
    return y + x || 'b'
  }

  // A tile: the scene inside a border, the accent's while it has the focus. A
  // press in one that has not gives it the focus, and reaches its scene too.
  const tileOf = (win) => {
    const active = win.id === current
    const b = drawnTiles[win.id]
    if (!b || b.x + b.w <= 0 || b.x >= deskW) return null
    return (
      <div
        className={`absolute left-[${b.x}px] top-[${b.y}px] w-[${b.w}px] h-[${b.h}px] flex flex-col border-[${border()}px] border-[${active ? t.accent : t.muted}]`}
      >
        {active ? <yield /> : <Scene id={win.id} onPointerDown={() => focus(win.id)} />}
      </div>
    )
  }

  // A floating window: its border, a title bar in the theme's colors and the scene.
  const floatOf = (win) => {
    const active = win.id === current
    const b = boxOf(win, deskW, usable(ws))
    const ink = active ? t.fg : t.muted
    const Button = ({ onClick, children }) => (
      <div className={`flex items-center justify-center shrink-0 w-[${size(24)}px] self-stretch active:bg-[${t.muted}]`} onClick={onClick}>
        {children}
      </div>
    )
    return (
      <div
        className={`absolute left-[${b.x}px] top-[${b.y}px] w-[${b.w}px] h-[${b.h}px] flex flex-col bg-[${t.bar}] border-[${border()}px] border-[${active ? t.accent : t.muted}]${win.max ? '' : ` cursor-resize-[${corner}px]`}`}
        {...(win.max
          ? {}
          : { onPointerDown: (e) => startDrag(win, edgeOf(e))(e), onPointerMove: dragTo, onPointerUp: endDrag })}
      >
        <div
          className={`flex items-center shrink-0 h-[${titleH()}px] pl-[${px(8)}] text-[${ink}] text-[${px(13)}] bg-[${active ? t.bar : t.bg}]`}
          onPointerDown={startDrag(win, 'move')}
          onPointerMove={dragTo}
          onPointerUp={endDrag}
          onDoubleClick={() => toggleMax(win.id)}
        >
          <span className="flex-1 min-w-0 truncate font-bold">{names[win.id]}</span>
          <Button onClick={() => minimize(win.id)}>
            <MinGlyph c={ink} />
          </Button>
          <Button onClick={() => toggleMax(win.id)}>
            <MaxGlyph c={ink} />
          </Button>
          <Button onClick={() => close(win.id)}>
            <CloseGlyph c={ink} />
          </Button>
        </div>
        <div className="relative flex flex-col flex-1 min-h-0">
          {active ? <yield /> : <Scene id={win.id} />}
          {/* A press on a window behind brings it forward, and is only that. */}
          {active ? null : <div className="absolute inset-0" onPointerDown={() => focus(win.id)} />}
        </div>
      </div>
    )
  }

  // Where a floating window let go now would go: its outline.
  const outline = () => {
    const drag = app.state.drag
    if (!drag || drag.mode !== 'move' || !drag.at || drag.docked) return null
    const b = boxOf({ max: drag.at === 'max', snap: drag.at }, deskW, usable(ws))
    const w = Math.max(2, border())
    const bar = (x, y, bw, bh) => <div className={`absolute left-[${x}px] top-[${y}px] w-[${bw}px] h-[${bh}px] bg-[${t.accent}]`} />
    return [bar(b.x, b.y, b.w, w), bar(b.x, b.y + b.h - w, b.w, w), bar(b.x, b.y, w, b.h), bar(b.x + b.w - w, b.y, w, b.h)]
  }

  // A floating workspace's dock: the frame's own apps, the other windows on it
  // (a dot under each, put away or not), and the whole menu.
  const dock = () => {
    const pinned = frameApps.map((scene) => scene.id)
    const items = [...pinned, ...onWs.map((w) => w.id).filter((id) => !pinned.includes(id))]
    const box = dockBox(items.length + 1)
    const Item = ({ id }) => {
      const scene = sceneOf(id)
      const icon = ownIcon(scene, px(22))
      return (
        <div className={`flex flex-col items-center shrink-0 w-[${size(42)}px] gap-[${px(3)}]`} onClick={() => open(id)}>
          <div
            className={`flex items-center justify-center w-[${size(36)}px] h-[${size(36)}px] text-[${t.fg}] ${
              id === current ? `bg-[${t.muted}]` : `bg-[${t.bg}]`
            } active:bg-[${t.accent}]`}
          >
            {icon || <Letter text={names[id]} t={t} s={22} lit={pinned.includes(id)} />}
          </div>
          <div className={`w-[${size(4)}px] h-[${size(4)}px] rounded-full ${isOpen(id) ? `bg-[${t.accent}]` : ''}`} />
        </div>
      )
    }
    return (
      <div
        className={`absolute left-[${box.x}px] top-[${box.y}px] w-[${box.w}px] h-[${box.h}px] flex items-center justify-center gap-[${px(4)}] bg-[${t.bar}] border-[${border()}px] border-[${t.muted}]`}
        onPointerDown={() => {}}
      >
        {items.map((id) => (
          <Item id={id} />
        ))}
        <div className={`flex flex-col items-center shrink-0 w-[${size(42)}px] gap-[${px(3)}]`} onClick={() => a.palette('apps')}>
          <div className={`flex items-center justify-center w-[${size(36)}px] h-[${size(36)}px] bg-[${t.bg}] active:bg-[${t.accent}]`}>
            <GridGlyph c={t.fg} />
          </div>
          <div className={`h-[${size(4)}px]`} />
        </div>
      </div>
    )
  }

  // The bar: the menu, the workspaces (the one showing in the accent, those with
  // windows brighter), the layout's mark and the window with the focus; the day and
  // the time; the signal and the battery. A swipe across it goes to the next
  // workspace, a double click on its empty stretch makes it transparent.
  const lastWs = Math.max(5, ws, ...wins.map((w) => w.ws || 1))
  const toggleClear = () => frameos.setState('clear', !clearBar)
  const shown = focused ? names[focused.id] : ''
  const bar = (className = '') => (
    <Bar
      t={t}
      clear={clearBar}
      className={className}
      onSwipe={(e) => (e.direction === 'left' ? a.stepWs(1) : e.direction === 'right' ? a.stepWs(-1) : null)}
      left={[
        <div
          className={`flex items-center justify-center shrink-0 w-[${size(24)}px] self-stretch ${menu === 'palette' ? `bg-[${t.muted}]` : ''} active:bg-[${t.muted}]`}
          onClick={() => (menu === 'palette' ? a.shut() : a.palette(null))}
        >
          <MenuGlyph c={t.accent} />
        </div>,
        ...Array.from({ length: lastWs }, (_, i) => i + 1).map((n) => (
          <div
            className={`flex items-center justify-center shrink-0 min-w-[${size(18)}px] h-[${size(18)}px] px-[${px(4)}] ${
              n === ws
                ? `bg-[${t.accent}] text-[${t.bg}] font-bold`
                : wins.some((w) => w.ws === n)
                  ? `text-[${t.fg}] active:bg-[${t.muted}]`
                  : `text-[${t.muted}] active:bg-[${t.muted}]`
            }`}
            onClick={() => a.toWorkspace(n)}
          >
            {String(n)}
          </div>
        )),
        <div className={`flex items-center justify-center shrink-0 w-[${size(22)}px] self-stretch active:bg-[${t.muted}]`} onClick={() => a.cycleLayout(1)}>
          <LayoutGlyph how={how} c={t.fg} />
        </div>,
        shown ? (
          <div className={`flex items-center min-w-0 px-[${px(4)}] self-stretch active:bg-[${t.muted}]`} onClick={() => a.palette('window')}>
            <span className="min-w-0 truncate">{shown}</span>
          </div>
        ) : null,
        <div className="flex-1 self-stretch" onDoubleClick={toggleClear} />,
      ]}
      middle={
        <div className={`flex items-center gap-[${px(6)}] px-[${px(4)}] self-stretch`} onClick={() => frameos.setState('week', !on(app.state.week))}>
          <span className="whitespace-nowrap">{DAYS[now.getDay()]}</span>
          <span className="whitespace-nowrap font-bold">{clock(now, on(app.state.twentyFourHour))}</span>
          {on(app.state.week) ? <span className={`whitespace-nowrap text-[${t.muted}]`}>{`W${isoWeek(now)}`}</span> : null}
        </div>
      }
      right={[<div className="flex-1 self-stretch" onDoubleClick={toggleClear} />, <Tray app={app} t={t} onClick={controlPanel} />]}
    />
  )

  // The menu: a field that filters, and its rows. With no filter: the frame's own
  // apps, its scenes by category, and the desktop's commands; a filter goes through
  // all of it. A command with more opens a page of its own.
  const page = app.state.page || null
  const query = String(app.state.query || '').trim().toLowerCase()
  const back = { label: 'Back', more: null, back: true }
  const sceneRow = (scene) => ({
    label: scene.name || scene.id,
    icon: ownIcon(scene, px(16)) || <Letter text={scene.name || scene.id} t={t} />,
    run: () => open(scene.id),
    check: isOpen(scene.id),
  })
  const appRows = frameApps.map((scene) => ({
    label: names[scene.id],
    icon: <Letter text={names[scene.id]} t={t} lit />,
    run: () => open(scene.id),
    check: isOpen(scene.id),
  }))
  const sceneRows = grouped(programs).flatMap((group) => [...(group.title ? [{ heading: group.title }] : []), ...group.scenes.map(sceneRow)])
  const S = superName(app)
  const sc = withCtrl(app)
  const windowRows = focused
    ? [
        ...(isSystem(focused.id) ? [] : [{ label: `${names[focused.id]} settings`, run: () => sceneSettings(focused.id) }]),
        { label: full ? 'Leave full screen' : 'Full screen', run: toggleFull, keys: `${S}+F` },
        ...(how === 'floating' ? [{ label: 'Put in the dock', run: () => minimize(focused.id), keys: `${S}+M` }] : []),
        ...Array.from({ length: lastWs }, (_, i) => i + 1)
          .filter((n) => n !== ws)
          .map((n) => ({ label: `Move to workspace ${n}`, run: () => a.moveTo(focused.id, n), keys: `${S}+Shift+${n % 10}` })),
        { label: 'Close', run: () => close(focused.id), keys: `${S}+W` },
      ]
    : []
  const keyRows = [
    { label: 'The menu', keys: `${S}+Space`, run: () => a.palette(null) },
    { label: 'Close the window', keys: `${S}+W`, run: () => focused && close(focused.id) },
    { label: 'Full screen', keys: `${S}+F`, run: toggleFull },
    { label: 'Next layout', keys: `${S}+L`, run: () => a.cycleLayout(1) },
    { label: 'Turn the split around', keys: `${S}+J`, run: a.toggleSplit },
    { label: 'Next workspace', keys: `${S}+Tab`, run: () => a.stepWs(1) },
    { label: 'Terminal', keys: `${S}+Return`, run: () => terminal && open(terminal.id) },
    { label: 'Files', keys: `${S}+Shift+F`, run: () => files && open(files.id) },
    { label: 'Setup', keys: sc ? `${S}+Ctrl+W` : null, run: controlPanel },
    { label: 'Next theme', keys: sc ? `${S}+Shift+Ctrl+Space` : null, run: a.nextScheme },
    ...(superMode(app) === 'alt' ? [] : [{ label: 'Next window', keys: 'Alt+Tab', run: () => a.cycle(false) }]),
  ]
  // What Super is here (the field `superKey`), over the bindings.
  const superIs = {
    both: 'Super is Cmd or the Windows key, or Ctrl',
    super: 'Super is Cmd or the Windows key',
    ctrl: 'Super is Ctrl',
    alt: 'Super is Alt',
  }[superMode(app)]
  const commands = [
    { label: 'Setup', run: controlPanel, keys: sc ? `${S}+Ctrl+W` : null },
    { label: 'Scenes', run: sceneList },
    ...(focused ? [{ label: 'Window', more: 'window' }] : []),
    { label: 'Layout', more: 'layout', keys: `${S}+L` },
    { label: 'Theme', more: 'theme' },
    { label: clearBar ? 'Solid bar' : 'Transparent bar', run: () => (a.shut(), toggleClear()) },
    { label: 'Keybindings', more: 'keys', keys: `${S}+K` },
  ]
  const pageRows = () => {
    if (page === 'theme')
      return [back, ...SCHEME_IDS.map((id) => ({ label: SCHEMES[id].name, run: () => a.setScheme(id), check: id === t.id, stay: true }))]
    if (page === 'layout')
      return [
        back,
        ...LAYOUTS.map((name) => ({ label: LAYOUT_NAMES[name], run: () => a.setLayout(name), check: name === how })),
        ...(how === 'dwindle' ? [{ label: 'Turn the split around', run: a.toggleSplit, keys: `${S}+J` }] : []),
      ]
    if (page === 'window') return [back, ...windowRows]
    if (page === 'keys') return [back, { heading: superIs }, ...keyRows]
    if (page === 'apps') return [...appRows, ...sceneRows]
    if (query) {
      const all = [...appRows, ...sceneRows.filter((row) => !row.heading), ...commands.filter((row) => row.run), ...windowRows, ...keyRows]
      return all.filter((row) => matches(row.label, query))
    }
    return [...appRows, ...sceneRows, { heading: 'Omarchy' }, ...commands]
  }
  const palette = () => {
    const rows = pageRows()
    const runnable = rows.filter((row) => !row.heading)
    const pick = Math.max(0, Math.min(Number(app.state.pick) || 0, runnable.length - 1))
    paletteRows = runnable.map((row) => () => runRow(row))
    const rowH = size(28)
    const headH = size(22)
    const fieldH = size(44)
    const w = Math.min(width - size(24), size(560))
    const listH = rows.reduce((n, row) => n + (row.heading ? headH : rowH), 0)
    const h = Math.min(Math.round(deskH * 0.86), 2 * border() + fieldH + size(8) + Math.max(rowH, listH))
    const x = Math.round((width - w) / 2)
    const y = deskTop + Math.max(size(8), Math.round((deskH - h) / 4))
    const titles = { theme: 'Theme', layout: 'Layout', window: shown || 'Window', keys: 'Keybindings', apps: 'Apps' }
    return (
      <div
        className={`absolute left-[${x}px] top-[${y}px] w-[${w}px] h-[${h}px] flex flex-col bg-[${t.bg}] text-[${t.fg}] text-[${px(14)}] border-[${border()}px] border-[${t.accent}]`}
        onPointerDown={() => {}}
      >
        <div className={`flex items-center shrink-0 h-[${fieldH}px] gap-[${px(8)}] px-[${px(12)}] border-b-1 border-[${t.muted}]`}>
          <SearchGlyph c={t.muted} />
          <input
            className={`flex-1 min-w-0 h-[${size(36)}px] px-[${px(4)}] bg-[${t.bg}] text-[${t.fg}] placeholder:text-[${t.muted}] focus:bg-[${t.bar}]`}
            value={String(app.state.query || '')}
            placeholder={page ? titles[page] || 'Search' : 'Search apps and commands'}
            onChange={(e) => {
              frameos.setState('query', String(e.target.value))
              frameos.setState('pick', 0)
            }}
            onKeyDown={(e) => (e.key === 'Enter' && app.state.menu === 'palette' && paletteRows[pick] ? paletteRows[pick]() : null)}
          />
        </div>
        <div className={`flex flex-col flex-1 min-h-0 overflow-y-auto py-[${px(4)}]`}>
          {rows.length ? (
            rows.map((row) =>
              row.heading ? (
                <div className={`flex items-center shrink-0 h-[${headH}px] px-[${px(14)}] text-[${px(12)}] font-bold text-[${t.muted}]`}>
                  <span className="flex-1 min-w-0 truncate">{row.heading}</span>
                </div>
              ) : (
                <div
                  className={`flex items-center shrink-0 h-[${rowH}px] gap-[${px(8)}] px-[${px(12)}] ${
                    runnable.indexOf(row) === pick ? `bg-[${t.bar}] text-[${t.accent}]` : ''
                  } hover:bg-[${t.bar}] active:bg-[${t.accent}] active:text-[${t.bg}]`}
                  onClick={() => runRow(row)}
                >
                  <div className={`flex items-center justify-center shrink-0 w-[${size(16)}px]`}>{row.icon || null}</div>
                  <span className="flex-1 min-w-0 truncate">{row.back ? '‹ Back' : row.more ? `${row.label} ›` : row.label}</span>
                  {row.check ? <div className={`w-[${size(6)}px] h-[${size(6)}px] rounded-full bg-[${t.accent}]`} /> : null}
                  {row.keys ? <span className={`shrink-0 text-[${px(12)}] text-[${t.muted}]`}>{row.keys}</span> : null}
                </div>
              ),
            )
          ) : (
            <div className={`flex items-center h-[${rowH}px] px-[${px(14)}] text-[${t.muted}]`}>Nothing matches</div>
          )}
        </div>
      </div>
    )
  }
  function runRow(row) {
    if (row.back) return a.palette(null)
    if (row.more) return a.palette(row.more)
    if (row.run) row.run()
    if (!row.stay) a.shut()
  }

  const cover = menu ? <div className="absolute inset-0" onPointerDown={() => a.shut()} onClick={() => {}} /> : null

  if (full) {
    // The panel is the window's. The pointer at the top edge brings the bar back;
    // moved back over the window, it goes again, unless the menu is open.
    const peek = on(app.state.peek) || !!menu
    return (
      <div className={`relative w-full h-full bg-[${t.bg}] text-[${t.fg}] text-[${px(13)}]`}>
        <div className="absolute inset-0 flex flex-col">
          <yield />
        </div>
        {!peek ? (
          <div className="absolute left-0 top-0 w-full h-[2px]" onPointerMove={() => frameos.setState('peek', true)} />
        ) : menu ? null : (
          <div className={`absolute left-0 top-[${deskTop}px] w-full h-[${deskH}px]`} onPointerMove={() => frameos.setState('peek', false)} />
        )}
        {cover}
        {peek ? bar('absolute left-0 top-0 w-full') : null}
        {menu === 'palette' ? palette() : null}
      </div>
    )
  }

  const floating = how === 'floating'
  const order = floating
    ? onWs
        .filter((w) => !w.min && !(focused && w.id === focused.id))
        .sort((x, y) => (x.z || 0) - (y.z || 0))
        .concat(focused ? [focused] : [])
    : onWs
  return (
    <div className={`relative w-full h-full bg-gradient-to-br from-[${t.bg}] to-[${t.wall}] text-[${t.fg}] text-[${px(13)}]`}>
      <div className={`absolute left-0 top-[${deskTop}px] w-[${deskW}px] h-[${deskH}px]`}>
        {order.map(floating ? floatOf : tileOf)}
        {floating ? outline() : null}
        {floating ? dock() : null}
      </div>
      {cover}
      {bar('absolute left-0 top-0 w-full')}
      {menu === 'palette' ? palette() : null}
    </div>
  )
}

// The keys, Omarchy's (Super is the key the field `superKey` says, chordOf):
// Super+Space the menu
// (with Alt, the apps alone), Super+K the bindings, Super+1 to 0 a workspace and
// with Shift the window goes there, Super+Tab the next workspace, Super+W or Q
// closes, Super+F full screen, Super+L the next layout (with Alt, the one
// before), Super+J turns the split around, Super+M puts a floating window in the
// dock, Super+arrows move the focus and with Shift swap the tiles, Super+Return
// the terminal, Super+Shift+F Files, Super+Ctrl+W, N, P, A or B Setup,
// Super+Shift+Ctrl+Space the next theme, Alt+Tab the next window. In the menu,
// the arrows pick a row, Enter runs it, Escape closes it. The scene heard the key
// first.
export function onEvent(app, context) {
  if (context.event !== 'keyDown' || !Array.isArray(app.frame.scenes) || !windowsOn(app)) return false
  const p = context.payload || {}
  const key = String(p.key || '')
  const code = String(p.code || '')
  // A letter by where it is on the keyboard: Alt on a Mac types another character.
  const lower = /^Key[A-Z]$/.test(code) ? code.slice(3).toLowerCase() : key.toLowerCase()
  const chord = chordOf(app, p)
  const a = actions(app)
  // The window with the focus, where it shows: on the workspace in view and out
  // of the dock. On an empty workspace, or with it docked, the keys that act on a
  // window have none (the focus is on a scene out of sight).
  const front = winsOf(app).find((w) =>
    w.id === app.frame.sceneId && (w.ws || 1) === wsOf(app) && !(w.min && layoutOf(app, wsOf(app)) === 'floating'))
  const id = front ? front.id : null
  if (key === 'Escape' && (app.state.menu || on(app.state.full))) {
    a.shut()
    frameos.setState('full', false)
    return true
  }
  if (app.state.menu === 'palette' && !chord.sup) {
    const pick = Number(app.state.pick) || 0
    if (key === 'ArrowDown' || key === 'ArrowUp') {
      const n = paletteRows.length
      if (n) frameos.setState('pick', (pick + (key === 'ArrowDown' ? 1 : n - 1)) % n)
      return true
    }
    if (key === 'Enter' && paletteRows[pick]) {
      paletteRows[pick]()
      return true
    }
  }
  if (key === 'Tab' && chord.alt && !chord.sup) return a.cycle(chord.shift)
  if (!chord.sup) return false
  const digit = /^Digit(\d)$/.exec(code) || (/^\d$/.test(key) ? [key, key] : null)
  if (digit) {
    const n = Number(digit[1]) || 10
    if (chord.shift) {
      if (id) a.moveTo(id, n)
    } else a.toWorkspace(n)
    return true
  }
  if (key === ' ' || code === 'Space') {
    if (chord.ctrl && chord.shift) a.nextScheme()
    else if (app.state.menu === 'palette') a.shut()
    else a.palette(chord.alt ? 'apps' : null)
    return true
  }
  const files = filesOf(app)
  const terminal = terminalOf(app)
  if (chord.ctrl && ['w', 'n', 'p', 'a', 'b'].includes(lower)) {
    a.controlPanel()
    return true
  }
  if (lower === 'tab') a.stepWs(chord.shift ? -1 : 1)
  else if ((lower === 'w' || lower === 'q') && id) a.close(id)
  else if (lower === 'f' && chord.shift) {
    if (!files) return false
    a.open(files.id)
  } else if (lower === 'f') a.toggleFull()
  else if (lower === 'l') a.cycleLayout(chord.alt ? -1 : 1)
  else if (lower === 'j') a.toggleSplit()
  else if (lower === 'k') a.palette('keys')
  else if (lower === 'm' && id) {
    if (layoutOf(app, wsOf(app)) !== 'floating') return false
    a.minimize(id)
  } else if (key === 'Enter') {
    if (!terminal) return false
    a.open(terminal.id)
  } else if (key.startsWith('Arrow')) return a.toward(key.slice(5).toLowerCase(), chord.shift)
  else return false
  return true
}

// Windows, or one scene at a time in the desktop's look (`windowMode`). Automatic
// is windows where the frame runs its scenes side by side without a limit (a Pi,
// the browser) or four at once, on a screen of 640x480 or more either way up,
// and one scene where it runs one or two (app.frame.windows: an ESP32 with 8 MB,
// where a window behind the one in front costs memory and frames, and a desktop
// of two is mostly the one in front) or the screen is smaller (a 480x480 panel
// has no room for a window beside another). An install from before, whose
// `windows` switch was turned off, stays off.
const windowsOn = (app) => {
  const mode = app.state.windowMode
  if (mode === 'on') return true
  if (mode === 'off' || app.state.windows === false || app.state.windows === 'false') return false
  const most = app.frame.windows
  const long = Math.max(app.frame.width || 0, app.frame.height || 0)
  const short = Math.min(app.frame.width || 0, app.frame.height || 0)
  return !(most > 0 && most <= 2) && long >= 640 && short >= 480
}

export function get(app) {
  // app.frame's size is the panel's over the render scale, before the frame's rotation.
  const turned = (app.frame.rotate || 0) % 180 !== 0
  const width = turned ? app.frame.height : app.frame.width
  const height = turned ? app.frame.width : app.frame.height
  const shortSide = Math.min(app.frame.width, app.frame.height)
  zoom = shortSide >= (app.frame.paper ? 1000 : 2160) ? 2 : shortSide >= 480 ? 1 : shortSide / 480
  const now = new Date()
  const t = schemeOf(app)
  dress(app, t)
  // The clock changes on the minute: nothing to draw until then.
  frameos.setNextSleep(60 - now.getSeconds())
  if (Array.isArray(app.frame.scenes) && windowsOn(app)) return desktop(app, now, width, height)
  // One scene at a time: nothing else is open, nothing for another layout to open.
  if (Array.isArray(app.state.openScenes) && app.state.openScenes.length) frameos.setState('openScenes', [])
  const name = app.frame.sceneName || 'FrameOS'
  const builtIn = app.frame.systemScene === true
  const settingsOpen = builtIn && name.includes('settings')
  const frameOpen = settingsOpen && name.startsWith('Frame')
  const listOpen = builtIn && !settingsOpen
  const title = listOpen ? 'Scenes' : frameOpen ? 'Setup' : settingsOpen ? `${app.state.openedOver || 'Scene'} settings` : name
  const clearBar = on(app.state.clear)
  const toggleClear = () => frameos.setState('clear', !clearBar)
  const out = gapOut()
  return (
    <div className={`flex flex-col w-full h-full bg-gradient-to-br from-[${t.bg}] to-[${t.wall}] text-[${t.fg}] text-[${px(13)}]`}>
      <Bar
        t={t}
        clear={clearBar}
        className="shrink-0"
        left={[
          <div
            className={`flex items-center justify-center shrink-0 w-[${size(24)}px] self-stretch ${listOpen ? `bg-[${t.muted}]` : ''} active:bg-[${t.muted}]`}
            onClick={() => frameos.dispatch('sceneSwitcher', { swap: true })}
          >
            <MenuGlyph c={t.accent} />
          </div>,
          <div className={`flex items-center justify-center shrink-0 min-w-[${size(18)}px] h-[${size(18)}px] px-[${px(4)}] bg-[${t.accent}] text-[${t.bg}] font-bold`}>1</div>,
          <div
            className={`flex items-center min-w-0 px-[${px(4)}] self-stretch ${settingsOpen && !frameOpen ? `bg-[${t.muted}]` : ''} active:bg-[${t.muted}]`}
            onClick={() => frameos.dispatch('sceneSettings')}
          >
            <span className="min-w-0 truncate">{title}</span>
          </div>,
          <div className="flex-1 self-stretch" onDoubleClick={toggleClear} />,
        ]}
        middle={
          <div className={`flex items-center gap-[${px(6)}] px-[${px(4)}]`}>
            <span className="whitespace-nowrap">{DAYS[now.getDay()]}</span>
            <span className="whitespace-nowrap font-bold">{clock(now, on(app.state.twentyFourHour))}</span>
          </div>
        }
        right={[
          <div className="flex-1 self-stretch" onDoubleClick={toggleClear} />,
          <Tray app={app} t={t} onClick={() => frameos.dispatch('sceneSettings', { page: 'frame' })} />,
        ]}
      />
      <div className={`flex flex-col flex-1 min-h-0 p-[${out}px]`}>
        <div className={`flex flex-col flex-1 min-h-0 border-[${border()}px] border-[${t.accent}]`}>
          <yield />
        </div>
      </div>
    </div>
  )
}
